import AVFoundation
import Capacitor
import EscouadeMobileCore
import Foundation
import LocalAuthentication
import Security
import Speech
import UIKit

/// MO-3 and MO-4: the mobile app's native side under iOS. The Rust (crates/escouade-mobile) through the Swift bindings
/// of UniFFI (generated by scripts/mobile-ios.sh into ios/Sources/EscouadeMobileCore, the library in
/// ios/escouade_mobileFFI.xcframework); each space's keys and token in the Keychain (SR1-15, ESC-570), readable after
/// the first unlock, on this device alone (kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly: never in a backup, never
/// on another iPhone). The JavaScript passes a space's id, never a key.
/// The API is src/definitions.ts; a failure rejects with the crate's error as the code (`Forged`, `BadKey`…).
@objc(EscouadeMobilePlugin)
public class EscouadeMobilePlugin: CAPPlugin, CAPBridgedPlugin {
    public let identifier = "EscouadeMobilePlugin"
    public let jsName = "EscouadeMobile"
    public let pluginMethods: [CAPPluginMethod] = [
        CAPPluginMethod(name: "lockState", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "unlock", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "readPairing", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "pairingKey", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "finishPairing", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "forgetSpace", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "startTunnel", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "tunnelStatus", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "stopTunnel", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "openNotification", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "version", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "dictate", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "stopDictation", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "openFile", returnType: CAPPluginReturnPromise),
    ]

    /// A space's way: its tunnel, or a proxy to its address.
    private enum Way {
        case tunnel(MobileTunnel)
        case direct(MobileDirect)

        func status() -> MobileTunnelStatus {
            switch self {
            case let .tunnel(t): return t.status()
            case let .direct(d): return d.status()
            }
        }

        func stop() {
            switch self {
            case let .tunnel(t): t.stop()
            case let .direct(d): d.stop()
            }
        }
    }

    /// One way per space.
    private var ways: [String: Way] = [:]
    /// The pairings under way, in memory alone: what was read, and the phone's private half.
    private var pending: [String: [String: String]] = [:]
    private var halves: [String: String] = [:]
    private let lock = NSLock()

    deinit {
        lock.lock()
        ways.values.forEach { $0.stop() }
        lock.unlock()
    }

    private func reject(_ call: CAPPluginCall, _ error: Error) {
        // The case's name (`Forged`, `BadKey`…) is the code, its text the message.
        let code = Mirror(reflecting: error).children.first?.label ?? "Io"
        let message = (error as? LocalizedError)?.errorDescription ?? "\(error)"
        call.reject(message, code)
    }

    private func stateName(_ state: MobileTunnelState) -> String {
        switch state {
        case .connecting: return "connecting"
        case .up: return "up"
        case .stopped: return "stopped"
        case .failed: return "failed"
        }
    }

    private func status(_ space: String, _ s: MobileTunnelStatus) -> [String: Any] {
        var o: [String: Any] = [
            "space": space,
            "state": stateName(s.state),
            "proxyUrl": s.proxyUrl,
            "websocketUrl": s.websocketUrl,
            "txBytes": Double(s.txBytes),
            "rxBytes": Double(s.rxBytes),
            "connections": Int(s.connections),
        ]
        if let h = s.lastHandshakeSecs { o["lastHandshakeSecs"] = Double(h) }
        if let e = s.error { o["error"] = e }
        return o
    }

    private func take(_ space: String) -> Way? {
        lock.lock()
        defer { lock.unlock() }
        return ways.removeValue(forKey: space)
    }

    // ---------- the Keychain ----------

    private let service = "dev.escouade.mobile.spaces"

    private func query(_ space: String) -> [String: Any] {
        [kSecClass as String: kSecClassGenericPassword, kSecAttrService as String: service, kSecAttrAccount as String: space]
    }

    private func keep(_ space: String, _ kept: [String: String]) -> Bool {
        guard let data = try? JSONSerialization.data(withJSONObject: kept) else { return false }
        SecItemDelete(query(space) as CFDictionary)
        var add = query(space)
        add[kSecValueData as String] = data
        add[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly
        return SecItemAdd(add as CFDictionary, nil) == errSecSuccess
    }

    private func kept(_ space: String) -> [String: String]? {
        var q = query(space)
        q[kSecReturnData as String] = true
        q[kSecMatchLimit as String] = kSecMatchLimitOne
        var out: AnyObject?
        guard SecItemCopyMatching(q as CFDictionary, &out) == errSecSuccess, let data = out as? Data else { return nil }
        return (try? JSONSerialization.jsonObject(with: data)) as? [String: String]
    }

    // ---------- the lock ----------

    private func screenLock() -> Bool {
        LAContext().canEvaluatePolicy(.deviceOwnerAuthentication, error: nil)
    }

    @objc func lockState(_ call: CAPPluginCall) {
        let context = LAContext()
        let strong = context.canEvaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, error: nil)
        var biometry = "none"
        if strong {
            switch context.biometryType {
            case .faceID: biometry = "face"
            case .touchID: biometry = "fingerprint"
            default: biometry = "none"
            }
        }
        call.resolve(["screenLock": screenLock(), "biometry": biometry])
    }

    @objc func unlock(_ call: CAPPluginCall) {
        let reason = call.getString("reason") ?? "Escouade"
        guard screenLock() else { return call.reject("no screen lock", "NoLock") }
        // Face ID or Touch ID, the phone's code as a fallback (M3).
        LAContext().evaluatePolicy(.deviceOwnerAuthentication, localizedReason: reason) { ok, _ in
            if ok { call.resolve() } else { call.reject("cancelled", "Cancelled") }
        }
    }

    // ---------- the pairing ----------

    @objc func readPairing(_ call: CAPPluginCall) {
        guard let space = call.getString("space") else { return call.reject("space is required", "BadConfig") }
        var kept: [String: String] = [:]
        var found: [String: Any] = [:]
        if let qr = call.getString("qr") {
            guard let data = qr.data(using: .utf8),
                  let read = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any],
                  read["escouade"] as? String == "pair/1",
                  let tunnel = read["tunnel"] as? [String: Any]
            else { return call.reject("not a QR code of Escouade's pairing", "BadPairing") }
            kept["kind"] = "tunnel"
            for k in ["privateKey", "peerPublicKey", "endpoint", "address", "api"] {
                kept[k] = tunnel[k] as? String ?? ""
            }
            found = [
                "kind": "tunnel",
                "name": read["name"] as? String ?? "",
                "here": read["here"] as? Bool ?? false,
                "version": read["version"] as? String ?? "",
                "code": read["code"] as? String ?? "",
                "expiresAt": read["expiresAt"] as? Double ?? 0,
                "endpoint": tunnel["endpoint"] as? String ?? "",
            ]
        } else if let api = call.getString("api") {
            let address = api.trimmingCharacters(in: .whitespaces)
            kept["kind"] = "direct"
            kept["api"] = address
            found = ["kind": "direct", "endpoint": address]
        } else {
            return call.reject("a QR code or an address", "BadConfig")
        }
        take(space)?.stop()
        lock.lock()
        halves.removeValue(forKey: space)
        pending[space] = kept
        lock.unlock()
        call.resolve(found)
    }

    @objc func pairingKey(_ call: CAPPluginCall) {
        guard let space = call.getString("space") else { return call.reject("space is required", "BadConfig") }
        // No pairing without a screen lock (M3, docs/MOBILE.md § 3.9).
        guard screenLock() else { return call.reject("no screen lock", "NoLock") }
        lock.lock()
        defer { lock.unlock() }
        guard pending[space] != nil else { return call.reject("no pairing under way", "NoSpace") }
        let key = EscouadeMobileCore.newPairingKey()
        halves[space] = key.privateKey
        call.resolve(["publicKey": key.publicKey])
    }

    @objc func finishPairing(_ call: CAPPluginCall) {
        guard let space = call.getString("space") else { return call.reject("space is required", "BadConfig") }
        let coreKey = call.getString("coreKey") ?? ""
        lock.lock()
        let read = pending[space]
        let half = halves[space]
        lock.unlock()
        guard var kept = read, let half else { return call.reject("no pairing under way", "NoSpace") }
        do {
            let p = try EscouadeMobileCore.finishPairing(privateKey: half, corePublicKey: coreKey)
            kept["token"] = p.deviceToken
            kept["pairingKey"] = p.pairingKey
            guard keep(space, kept) else { return call.reject("the Keychain refused the space", "Io") }
            lock.lock()
            pending.removeValue(forKey: space)
            halves.removeValue(forKey: space)
            lock.unlock()
            take(space)?.stop()
            call.resolve()
        } catch {
            reject(call, error)
        }
    }

    @objc func forgetSpace(_ call: CAPPluginCall) {
        guard let space = call.getString("space") else { return call.reject("space is required", "BadConfig") }
        take(space)?.stop()
        lock.lock()
        pending.removeValue(forKey: space)
        halves.removeValue(forKey: space)
        lock.unlock()
        SecItemDelete(query(space) as CFDictionary)
        call.resolve()
    }

    // ---------- the way to a space ----------

    @objc func startTunnel(_ call: CAPPluginCall) {
        guard let space = call.getString("space") else { return call.reject("space is required", "BadConfig") }
        lock.lock()
        let under = pending[space]
        lock.unlock()
        guard let kept = kept(space) ?? under else { return call.reject("nothing kept of this space", "NoSpace") }
        let token = kept["token"].flatMap { $0.isEmpty ? nil : $0 }
        take(space)?.stop()
        do {
            let way: Way
            if kept["kind"] == "direct" {
                way = .direct(try MobileDirect.start(api: kept["api"] ?? "", deviceToken: token))
            } else {
                let config = MobileTunnelConfig(
                    privateKey: kept["privateKey"] ?? "",
                    peerPublicKey: kept["peerPublicKey"] ?? "",
                    presharedKey: nil,
                    endpoint: kept["endpoint"] ?? "",
                    address: kept["address"] ?? "",
                    api: kept["api"] ?? "",
                    keepaliveSecs: nil,
                    deviceToken: token
                )
                way = .tunnel(try MobileTunnel.start(config: config))
            }
            lock.lock()
            ways[space] = way
            lock.unlock()
            call.resolve(status(space, way.status()))
        } catch {
            reject(call, error)
        }
    }

    @objc func tunnelStatus(_ call: CAPPluginCall) {
        guard let space = call.getString("space") else { return call.reject("space is required", "BadConfig") }
        lock.lock()
        let way = ways[space]
        lock.unlock()
        guard let way else { return call.reject("no tunnel for this space", "NoTunnel") }
        call.resolve(status(space, way.status()))
    }

    @objc func stopTunnel(_ call: CAPPluginCall) {
        guard let space = call.getString("space") else { return call.reject("space is required", "BadConfig") }
        take(space)?.stop()
        call.resolve()
    }

    @objc func openNotification(_ call: CAPPluginCall) {
        guard let space = call.getString("space") else { return call.reject("space is required", "BadConfig") }
        guard let key = kept(space)?["pairingKey"] else { return call.reject("nothing kept of this space", "NoSpace") }
        do {
            let n = try EscouadeMobileCore.openNotification(
                pairingKey: key,
                sealed: call.getString("sealed") ?? "",
                guardState: call.getString("guardState") ?? ""
            )
            var o: [String: Any] = [
                "seq": Double(n.seq),
                "at": Double(n.at),
                "kind": n.kind,
                "title": n.title,
                "body": n.body,
                "guardState": n.guardState,
            ]
            if let t = n.target { o["target"] = t }
            call.resolve(o)
        } catch {
            reject(call, error)
        }
    }

    @objc func version(_ call: CAPPluginCall) {
        call.resolve(["version": EscouadeMobileCore.mobileVersion()])
    }

    // ---------- the dictation (M9) and the files of a request (MO-5) ----------

    /// The dictation under way: its engine, its request, its task, and the call it answers.
    private var hearing: (engine: AVAudioEngine, request: SFSpeechAudioBufferRecognitionRequest, task: SFSpeechRecognitionTask?, call: CAPPluginCall)?

    /// The system's speech recognizer, on the device when it supports it (`requiresOnDeviceRecognition`): the audio
    /// never leaves the phone for Escouade's core. It listens until `stopDictation`, then answers what it heard.
    @objc func dictate(_ call: CAPPluginCall) {
        let lang = call.getString("lang") ?? "fr-FR"
        SFSpeechRecognizer.requestAuthorization { status in
            guard status == .authorized else { return call.reject("dictation not allowed", "NoDictation") }
            AVAudioSession.sharedInstance().requestRecordPermission { granted in
                guard granted else { return call.reject("microphone not allowed", "NoDictation") }
                DispatchQueue.main.async { self.listen(call, lang) }
            }
        }
    }

    private func listen(_ call: CAPPluginCall, _ lang: String) {
        guard hearing == nil, let recognizer = SFSpeechRecognizer(locale: Locale(identifier: lang)), recognizer.isAvailable else {
            return call.reject("no dictation on this phone", "NoDictation")
        }
        let request = SFSpeechAudioBufferRecognitionRequest()
        request.shouldReportPartialResults = false
        if recognizer.supportsOnDeviceRecognition { request.requiresOnDeviceRecognition = true }
        let engine = AVAudioEngine()
        do {
            let session = AVAudioSession.sharedInstance()
            try session.setCategory(.record, mode: .measurement, options: .duckOthers)
            try session.setActive(true, options: .notifyOthersOnDeactivation)
            let input = engine.inputNode
            input.installTap(onBus: 0, bufferSize: 1024, format: input.outputFormat(forBus: 0)) { buffer, _ in request.append(buffer) }
            engine.prepare()
            try engine.start()
        } catch {
            return call.reject("no dictation on this phone", "NoDictation")
        }
        call.keepAlive = true
        hearing = (engine, request, nil, call)
        hearing?.task = recognizer.recognitionTask(with: request) { [weak self] result, error in
            guard let self, let heard = self.hearing, heard.call === call else { return }
            if let result, result.isFinal {
                self.endHearing()
                let text = result.bestTranscription.formattedString
                if text.isEmpty { call.reject("nothing heard", "Cancelled") } else { call.resolve(["text": text]) }
            } else if error != nil {
                self.endHearing()
                call.reject("nothing heard", "Cancelled")
            }
        }
    }

    private func endHearing() {
        guard let heard = hearing else { return }
        hearing = nil
        heard.engine.stop()
        heard.engine.inputNode.removeTap(onBus: 0)
        heard.request.endAudio()
        heard.call.keepAlive = false
        try? AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation)
    }

    @objc func stopDictation(_ call: CAPPluginCall) {
        DispatchQueue.main.async {
            // The audio ends: the recognizer gives its last result, which answers `dictate`.
            self.hearing?.engine.stop()
            self.hearing?.engine.inputNode.removeTap(onBus: 0)
            self.hearing?.request.endAudio()
            call.resolve()
        }
    }

    /// A file of a request, written in the app's temporary folder (the system empties it), shared to the app that reads it.
    @objc func openFile(_ call: CAPPluginCall) {
        let name = (call.getString("name") ?? "file").replacingOccurrences(of: "/", with: "_")
        _ = call.getString("mediaType")
        guard let data = Data(base64Encoded: call.getString("data") ?? "") else { return call.reject("not base64", "Io") }
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("escouade-files", isDirectory: true)
        let url = dir.appendingPathComponent(name)
        do {
            try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
            try data.write(to: url, options: [.atomic, .completeFileProtection])
        } catch {
            return call.reject("cannot write the file", "Io")
        }
        DispatchQueue.main.async {
            guard let vc = self.bridge?.viewController else { return call.reject("no app opens this file", "NoApp") }
            let share = UIActivityViewController(activityItems: [url], applicationActivities: nil)
            share.popoverPresentationController?.sourceView = vc.view
            vc.present(share, animated: true) { call.resolve() }
        }
    }
}
